use std::{fs,io::Write,path::Path,process::{Command,Stdio}};
use gtkg_core::{CallContext,Dispatcher,EffectPolicy,TransportKind};
use gtkg_protocol::v2::{OperationRequestV2,PROTOCOL_VERSION_V2,V2ErrorCode};
use serde_json::{Value,json};
fn git(root:&Path,args:&[&str])->String{let o=Command::new("git").arg("-C").arg(root).args(args).output().expect("git");assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));String::from_utf8(o.stdout).expect("utf8").trim().into()}
fn fixture()->(tempfile::TempDir,Value){let t=tempfile::tempdir().expect("temp");let repo=t.path().join("repo");fs::create_dir(&repo).expect("repo");git(&repo,&["init","-q"]);let bytes=b"# Session restoration\nWhen a session is missing return new_session_required.\n";let mut input=format!("blob\nmark :1\ndata {}\n",bytes.len()).into_bytes();input.extend(bytes);input.extend(b"\ncommit refs/heads/main\ncommitter Fixture <fixture@example.invalid> 0 +0000\ndata 3\nqk\n\nM 100644 :1 README.md\n\n");let mut child=Command::new("git").arg("-C").arg(&repo).args(["fast-import","--quiet"]).stdin(Stdio::piped()).spawn().expect("fast import");child.stdin.take().expect("stdin").write_all(&input).expect("write");assert!(child.wait().expect("wait").success());let commit=git(&repo,&["rev-parse","main"]);let tree=git(&repo,&["rev-parse","main^{tree}"]);fs::create_dir(t.path().join("work")).expect("workspace");let payload=json!({"payload_revision":"gtkg.knowledge-quality/v0.4-r1","repository_id":"fixture","source_root":repo,"source_commit":commit,"expected_tree":tree,"output_path":t.path().join("work/archive"),"policy":{"revision":"all/v1","rules":[],"archive_binary":false}});(t,payload)}
fn request(op:&str,payload:Value)->OperationRequestV2{OperationRequestV2{protocol_version:PROTOCOL_VERSION_V2.into(),operation_id:op.into(),request_id:"v04-test".into(),payload}}
#[test]fn exact_source_and_manifest_plan_are_callable_through_shared_dispatcher(){let(t,p)=fixture();let w=t.path().join("work");let ctx=CallContext::restricted(TransportKind::Test,vec![w.clone(),t.path().join("repo")],EffectPolicy::WorkspaceWrite).expect("context");let source=Dispatcher.execute_v2(&ctx,request("source.capture",p)).expect("source capture successor");assert_eq!(source.result["total_paths"],1);let plan=Dispatcher.execute_v2(&ctx,request("analysis.plan",json!({"payload_revision":"gtkg.knowledge-quality/v0.4-r1","workspace_root":w,"artifact_ref":source.result["artifact_ref"]}))).expect("manifest plan successor");assert_eq!(plan.result["status"],"planned");assert_eq!(plan.result["selected_files"],1);}
#[test]fn successor_respects_authorized_roots_and_read_only_effect_policy(){let(t,mut p)=fixture();let w=t.path().join("work");let ctx=CallContext::restricted(TransportKind::Test,vec![w.clone()],EffectPolicy::WorkspaceWrite).expect("context");assert!(Dispatcher.execute_v2(&ctx,request("source.capture",p.clone())).is_err());assert!(!w.join("archive").exists());let ctx=CallContext::restricted(TransportKind::Test,vec![w,t.path().join("repo")],EffectPolicy::ReadOnly).expect("context");let e=Dispatcher.execute_v2(&ctx,request("source.capture",p.clone())).expect_err("read-only denial");assert_eq!(e.error.code,V2ErrorCode::SideEffectDenied);p["output_path"]=p["source_root"].clone();let write=CallContext::restricted(TransportKind::Test,vec![t.path().to_owned()],EffectPolicy::WorkspaceWrite).expect("context");assert!(Dispatcher.execute_v2(&write,request("source.capture",p)).is_err());}
#[test]fn explicit_capability_profile_is_discoverable(){let t=tempfile::tempdir().expect("temp");let c=CallContext::restricted(TransportKind::Test,vec![t.path().to_owned()],EffectPolicy::ReadOnly).expect("context");let r=Dispatcher.execute_v2(&c,request("capability.describe",json!({"payload_revision":"gtkg.knowledge-quality/v0.4-r1","capability_profile":"GTKG-V0.4-KNOWLEDGE-QUALITY"}))).expect("profile");assert_eq!(r.result["public_operation_count"],46);assert_eq!(r.result["languages"].as_array().expect("languages").len(),5);assert_eq!(r.result["target_execution"],false);}
#[test]fn successor_failures_keep_their_dedicated_code_instead_of_collapsing_to_invalid_request(){
 let(t,p)=fixture();let w=t.path().join("work");
 let ctx=CallContext::restricted(TransportKind::Test,vec![w.clone(),t.path().join("repo")],EffectPolicy::WorkspaceWrite).expect("context");
 // An unauthorized output path is a path escape, not a malformed request.
 let mut escape=p.clone();escape["output_path"]=json!("/gtkg-outside-the-authorized-roots");
 assert_eq!(Dispatcher.execute_v2(&ctx,request("source.capture",escape)).expect_err("escape").error.code,V2ErrorCode::PathEscape);
 // An archive that contains its own source is reported as an overlap.
 let mut overlap=p.clone();overlap["output_path"]=overlap["source_root"].clone();
 assert_eq!(Dispatcher.execute_v2(&ctx,request("source.capture",overlap)).expect_err("overlap").error.code,V2ErrorCode::SourceOutputOverlap);
 // A missing artifact stays distinct from a malformed payload.
 let missing=json!({"payload_revision":"gtkg.knowledge-quality/v0.4-r1","workspace_root":w,"artifact_ref":{"path":".gtkg/qk/plans/missing.json","sha256":format!("sha256:{}","0".repeat(64))}});
 assert_eq!(Dispatcher.execute_v2(&ctx,request("analysis.plan",missing)).expect_err("missing").error.code,V2ErrorCode::NotFound);
 // A closed-schema violation is still an invalid request.
 assert_eq!(Dispatcher.execute_v2(&ctx,request("analysis.plan",json!({"payload_revision":"gtkg.knowledge-quality/v0.4-r1","workspace_root":w,"bogus":1}))).expect_err("malformed").error.code,V2ErrorCode::InvalidRequest);
}
